'use strict';
const $=id=>document.getElementById(id);
const state={mode:'days',period:'mean',lower:20,upper:25,zoom:1,panX:0,panY:0,meta:null,source:null,country:null,selected:null,grid:null,request:0,ready:false};
const cache=new Map();
const fmt=new Intl.NumberFormat('en',{minimumFractionDigits:1,maximumFractionDigits:1});
const allowedPeriods=['mean','2020','2021','2022','2023','2024'];
const stage=$('map-stage');
const status=$('map-status');
function message(text){status.textContent=text;status.hidden=false;}
async function get(url,binary=false){const r=await fetch(url);if(!r.ok)throw new Error(`HTTP ${r.status}`);return binary?r.arrayBuffer():r.json();}
function loadGrid(period){if(!cache.has(period))cache.set(period,Promise.all([get(`assets/score-${period}.bin`,true),get(`assets/days-${period}.bin`,true)]).then(([score,days])=>({score:new Uint16Array(score),days:new Uint16Array(days)})).catch(e=>{cache.delete(period);throw e;}));return cache.get(period);}
function updateLabels(){const days=state.mode==='days';if(state.meta.land_cells)$('coverage-value').textContent=(100*state.meta.period_stats[state.period].score.valid_land_cells/state.meta.land_cells).toFixed(2)+'%';$('score-button').setAttribute('aria-pressed',String(!days));$('days-button').setAttribute('aria-pressed',String(days));$('score-card').classList.toggle('active',!days);$('days-card').classList.toggle('active',days);$('map-title').textContent=days?'Comfortable days per year':'Average comfort score';$('map-description').textContent=days?(state.period==='mean'?`Days with highs ${state.lower}–${state.upper} °C and rain ≤1 mm, counted over 2020–2024 and divided by 5.`:`Days in ${state.period} with highs ${state.lower}–${state.upper} °C and rain ≤1 mm. Both limits are inclusive.`):`100 points in ${state.lower}–${state.upper} °C; −1 per °C outside, plus −1 when rain >1 mm.`;$('days-value-label').textContent=state.period==='mean'?'Comfortable days per year':`Comfortable days in ${state.period}`;$('legend-title').textContent=days?(state.period==='mean'?`Comfortable days/year · ${state.lower}–${state.upper} °C · rain ≤1 mm`:`Comfortable days in ${state.period} · rain ≤1 mm`):'Average daily score';const ticks=days?['0','30','60','90','120','150+']:['≤76','82','87','93','98+'];$('legend-ticks').replaceChildren(...ticks.map(t=>{const el=document.createElement('span');el.textContent=t;return el;}));$('legend-low').textContent=days?'Fewer comfortable days':'Lower comfort';$('legend-high').textContent=days?'More comfortable days':'Higher comfort';$('heading-range').textContent=`${state.lower} to ${state.upper} °C`;$('days-unit').textContent=`high ${state.lower}–${state.upper} °C · rain ≤1 mm`;$('reading-example').textContent=`${state.lower-1} °C with 2 mm of rain gets 98 points: −1 for temperature and −1 for rain. It is not a comfortable day.`;$('map-image').alt=`Map of Europe: ${days?'comfortable days per year':'comfort score'}, ${state.period==='mean'?'2020–2024 average':state.period}`;}
function setUrl(){const u=new URL(location.href);u.searchParams.delete('visao');u.searchParams.delete('ano');u.searchParams.set('view',state.mode);if(state.period==='mean')u.searchParams.delete('year');else u.searchParams.set('year',state.period);if(state.lower!==20||state.upper!==25){u.searchParams.set('min',state.lower);u.searchParams.set('max',state.upper);}else{u.searchParams.delete('min');u.searchParams.delete('max');}history.replaceState(null,'',u);}
let climateWorker=null,workerId=0;const jobs=new Map();
function calculateDynamic(){if(!climateWorker){climateWorker=new Worker('climate-worker.js');climateWorker.onmessage=({data})=>{const job=jobs.get(data.id);if(!job)return;jobs.delete(data.id);if(data.error)job.reject(new Error(data.error));else job.resolve(data);};climateWorker.onerror=()=>{for(const job of jobs.values())job.reject(new Error('Recalculation failed. Reload the page.'));jobs.clear();};}const id=++workerId;return new Promise((resolve,reject)=>{jobs.set(id,{resolve,reject});climateWorker.postMessage({id,period:state.period,mode:state.mode,lower:state.lower,upper:state.upper});});}
async function render(){if(!state.meta)return;const request=++state.request;state.ready=false;$('export-map').disabled=true;stage.classList.add('loading');message('Loading view…');updateLabels();setUrl();try{const custom=state.lower!==20||state.upper!==25;if(custom){message('Recalculating map… The first use downloads data for this period.');const data=await calculateDynamic();if(request!==state.request)return;state.grid={score:data.score,days:data.days,exact:true};const canvas=$('dynamic-map');canvas.width=data.width;canvas.height=data.height;canvas.getContext('2d').putImageData(new ImageData(data.pixels,data.width,data.height),0,0);$('map-image').hidden=true;canvas.hidden=false;$('dynamic-overlay').hidden=false;}else{const src=`assets/${state.mode}-${state.period}.webp`,picture=new Image();picture.src=src;const [grid]=await Promise.all([loadGrid(state.period),picture.decode()]);if(request!==state.request)return;state.grid=grid;$('map-image').src=src;$('map-image').hidden=false;$('dynamic-map').hidden=true;$('dynamic-overlay').hidden=true;}state.ready=true;$('export-map').disabled=!!state.exporting;$('export-status').textContent='Full map · your selected range and period · 2400 px';stage.classList.remove('loading');status.hidden=true;$('range-message').textContent=`Applied range: ${state.lower}–${state.upper} °C, including both endpoints.`;if(state.selected)inspect(state.selected.lon,state.selected.lat,state.selected.label);else clearValues();}catch(e){if(request!==state.request)return;stage.classList.remove('loading');message(`Could not load this view. ${e.message}`);console.error('Map loading failed:',e.message);}}

function clearValues(){for(const id of ['point-score','point-days'])$(id).textContent='—';$('point-details').hidden=true;}
function nearest(a,value){let left=0,right=a.length-1;while(left<right){const middle=Math.floor((left+right)/2);if(a[middle]<value)left=middle+1;else right=middle;}return left>0&&Math.abs(a[left-1]-value)<Math.abs(a[left]-value)?left-1:left;}
function findCell(lon,lat){const m=state.meta;const rows=m.shape[0],cols=m.shape[1];if(lon<m.longitude[0]-.1||lon>m.longitude[cols-1]+.1||lat<m.latitude[0]-.1||lat>m.latitude[rows-1]+.1)return null;const i=nearest(m.latitude,lat),j=nearest(m.longitude,lon);let best=null;for(let dy=-2;dy<=2;dy++)for(let dx=-2;dx<=2;dx++){const y=i+dy,x=j+dx;if(x<0||x>=cols||y<0||y>=rows)continue;const index=y*cols+x;if(!state.source[index]||(state.grid.exact?(!Number.isFinite(state.grid.score[index])||!Number.isFinite(state.grid.days[index])):(state.grid.score[index]===65535||state.grid.days[index]===65535)))continue;const distance=Math.hypot(m.latitude[y]-lat,m.longitude[x]-lon);if(distance>.21)continue;if(!best||distance<best.distance)best={index,i:y,j:x,distance,nearby:x!==j||y!==i};}return best;}
function project(lon,lat){return proj4('EPSG:4326',state.meta.projection,[lon,lat]);}
function projectedFraction(lon,lat){const [x,y]=project(lon,lat);const [xmin,xmax,ymin,ymax]=state.meta.extent;return [(x-xmin)/(xmax-xmin),(ymax-y)/(ymax-ymin)];}
function inspect(lon,lat,label=''){state.selected={lon,lat,label};if(!state.ready){clearValues();return;}const cell=findCell(lon,lat);const period=state.period==='mean'?'2020–2024 average':state.period;if(!cell){$('place-title').textContent=label||'No sample in this area';$('place-subtitle').textContent='Select a land area with complete data.';clearValues();$('map-marker').hidden=true;return;}const country=state.meta.countries[state.country[cell.index]]||'Area of Europe';$('place-title').textContent=label||country;$('place-subtitle').textContent=`${period} · ${label?country:cell.nearby?'nearby valid cell':'grid cell'}`;$('point-score').textContent=fmt.format(state.grid.score[cell.index]/(state.grid.exact?1:100));$('point-days').textContent=fmt.format(state.grid.days[cell.index]/(state.grid.exact?1:10));$('point-details').hidden=false;const m=state.meta;const source=state.source[cell.index];$('point-coordinates').textContent=`Cell: ${m.latitude[cell.i].toFixed(2)}°, ${m.longitude[cell.j].toFixed(2)}°${cell.nearby?' · nearby sample':''}`;$('point-source').textContent=m.source_names[String(source)];$('point-resolution').textContent=source===1?'Approximate resolution: 11 km from north to south.':'Original resolution: about 55 km from north to south.';const [x,y]=projectedFraction(lon,lat);$('map-marker').style.left=`${x*100}%`;$('map-marker').style.top=`${y*100}%`;$('map-marker').hidden=false;}
function transform(){const r=stage.getBoundingClientRect();const maxX=r.width*(state.zoom-1)/2,maxY=r.height*(state.zoom-1)/2;state.panX=Math.max(-maxX,Math.min(maxX,state.panX));state.panY=Math.max(-maxY,Math.min(maxY,state.panY));$('map-content').style.transform=`translate(${state.panX}px,${state.panY}px) scale(${state.zoom})`;$('zoom-out').disabled=state.zoom<=1;$('zoom-in').disabled=state.zoom>=5;}
function zoom(value){const old=state.zoom;state.zoom=Math.max(1,Math.min(5,value));const ratio=state.zoom/old;state.panX*=ratio;state.panY*=ratio;transform();}
function reset(){state.zoom=1;state.panX=0;state.panY=0;transform();}
function clientPoint(x,y){const r=stage.getBoundingClientRect();const fx=((x-r.left-r.width/2-state.panX)/state.zoom+r.width/2)/r.width;const fy=((y-r.top-r.height/2-state.panY)/state.zoom+r.height/2)/r.height;const [xmin,xmax,ymin,ymax]=state.meta.extent;return proj4(state.meta.projection,'EPSG:4326',[xmin+fx*(xmax-xmin),ymax-fy*(ymax-ymin)]);}
let drag=null;
stage.addEventListener('pointerdown',e=>{if(e.target.closest('button')||!state.meta||!state.ready)return;drag={id:e.pointerId,x:e.clientX,y:e.clientY,panX:state.panX,panY:state.panY,moved:false};stage.setPointerCapture(e.pointerId);});
stage.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(dx,dy)>5){drag.moved=true;stage.classList.add('dragging');}if(drag.moved){state.panX=drag.panX+dx;state.panY=drag.panY+dy;transform();}});
stage.addEventListener('pointerup',e=>{if(!drag||e.pointerId!==drag.id)return;const wasDrag=drag.moved;drag=null;stage.classList.remove('dragging');if(stage.hasPointerCapture(e.pointerId))stage.releasePointerCapture(e.pointerId);if(!wasDrag&&state.ready){const [lon,lat]=clientPoint(e.clientX,e.clientY);inspect(lon,lat);}});
stage.addEventListener('pointercancel',()=>{drag=null;stage.classList.remove('dragging');});
stage.addEventListener('wheel',e=>{if(!state.ready)return;e.preventDefault();zoom(state.zoom*(e.deltaY<0?1.15:1/1.15));},{passive:false});
stage.addEventListener('keydown',e=>{if(e.target!==stage)return;const actions={'+':()=>zoom(state.zoom*1.4),'=':()=>zoom(state.zoom*1.4),'-':()=>zoom(state.zoom/1.4),'Home':reset,'ArrowLeft':()=>{state.panX+=40;transform();},'ArrowRight':()=>{state.panX-=40;transform();},'ArrowUp':()=>{state.panY+=40;transform();},'ArrowDown':()=>{state.panY-=40;transform();},'Enter':()=>{if(state.ready){const r=stage.getBoundingClientRect();const [lon,lat]=clientPoint(r.left+r.width/2,r.top+r.height/2);inspect(lon,lat);}}};if(actions[e.key]){e.preventDefault();actions[e.key]();}});
$('zoom-in').addEventListener('click',()=>zoom(state.zoom*1.4));$('zoom-out').addEventListener('click',()=>zoom(state.zoom/1.4));$('reset-map').addEventListener('click',reset);
for(const button of document.querySelectorAll('[data-mode]'))button.addEventListener('click',()=>{if(state.mode===button.dataset.mode)return;state.mode=button.dataset.mode;render();});
$('period').addEventListener('change',e=>{state.period=e.target.value;render();});
for(const button of document.querySelectorAll('[data-place]'))button.addEventListener('click',()=>{if(!state.meta||!state.ready)return;const lon=Number(button.dataset.lon),lat=Number(button.dataset.lat);inspect(lon,lat,button.dataset.place);if(state.zoom>1){const [fx,fy]=projectedFraction(lon,lat);const r=stage.getBoundingClientRect();state.panX=-(fx-.5)*r.width*state.zoom;state.panY=-(fy-.5)*r.height*state.zoom;transform();}});
$('range-form').addEventListener('submit',e=>{e.preventDefault();const lower=Number($('range-lower').value),upper=Number($('range-upper').value);if(!Number.isInteger(lower)||!Number.isInteger(upper)||lower>=upper||lower< -30||upper>50){$('range-message').textContent='Use whole-degree limits between −30 and 50 °C. The minimum must be below the maximum.';return;}state.lower=lower;state.upper=upper;render();});$('default-range').addEventListener('click',()=>{state.lower=20;state.upper=25;$('range-lower').value=20;$('range-upper').value=25;render();});
const dialog=$('method-dialog');for(const id of ['method-button','method-footer'])$(id).addEventListener('click',()=>dialog.showModal());$('close-method').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
window.addEventListener('resize',transform);
async function init(){try{const [meta,source,country]=await Promise.all([get('assets/metadata.json'),get('assets/source.bin',true),get('assets/country.bin',true)]);state.meta=meta;$('coverage-value').textContent=(meta.coverage*100).toFixed(2)+'%';state.source=new Uint8Array(source);state.country=new Uint8Array(country);const q=new URLSearchParams(location.search);state.mode=q.get('view')==='score'||(!q.has('view')&&q.get('visao')==='nota')?'score':'days';const requestedYear=q.get('year')||q.get('ano');state.period=allowedPeriods.includes(requestedYear)?requestedYear:'mean';const lo=q.has('min')?Number(q.get('min')):20,hi=q.has('max')?Number(q.get('max')):25;if(Number.isInteger(lo)&&Number.isInteger(hi)&&lo<hi&&lo>=-30&&hi<=50){state.lower=lo;state.upper=hi;}$('range-lower').value=state.lower;$('range-upper').value=state.upper;$('period').value=state.period;transform();await render();}catch(e){message('Could not load the data. Reload the page to try again.');console.error('Map initialization failed:',e.message);}}
init();
